module.exports = "const API = '/api';\n// Session token lives in sessionStorage: cleared when the tab closes, never\n// written to localStorage/disk, and separate from the password itself —\n// so the raw password is only ever sent once, at login.\nconst SESSION_KEY = 'tffm_admin_token';\n\nfunction getToken() { return sessionStorage.getItem(SESSION_KEY); }\nfunction setToken(t) { sessionStorage.setItem(SESSION_KEY, t); }\nfunction clearToken() { sessionStorage.removeItem(SESSION_KEY); }\n\nfunction showToast(text, isErr) {\n  const t = document.getElementById('toast');\n  t.textContent = text;\n  t.className = 'toast show ' + (isErr ? 'err' : 'ok');\n  setTimeout(() => t.classList.remove('show'), 2500);\n}\n\nfunction showAdmin() {\n  document.getElementById('loginBox').style.display = 'none';\n  document.getElementById('adminBody').style.display = 'block';\n  initAdmin();\n}\nfunction showLogin() {\n  document.getElementById('loginBox').style.display = 'block';\n  document.getElementById('adminBody').style.display = 'none';\n}\n\n// ---------- Login ----------\ndocument.getElementById('loginBtn').addEventListener('click', async () => {\n  const pw = document.getElementById('loginPw').value;\n  try {\n    const res = await fetch(`${API}/admin/login`, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ password: pw })\n    });\n    const data = await res.json();\n    if (!res.ok || !data.token) throw new Error(data.error || 'Wrong password');\n    setToken(data.token);\n    document.getElementById('loginPw').value = '';\n    showAdmin();\n  } catch (e) {\n    showToast('Incorrect password', true);\n  }\n});\n\n// ---------- Logout ----------\ndocument.getElementById('logoutBtn').addEventListener('click', async () => {\n  try {\n    await fetch(`${API}/admin/logout`, { method: 'POST', headers: { 'x-admin-token': getToken() } });\n  } catch (e) { /* best effort */ }\n  clearToken();\n  showLogin();\n  showToast('Logged out');\n});\n\nfunction authHeaders() {\n  return { 'Content-Type': 'application/json', 'x-admin-token': getToken() };\n}\n\n// If a request comes back 401, the session expired — bounce to login.\nasync function authedFetch(url, options) {\n  const res = await fetch(url, options);\n  if (res.status === 401) {\n    clearToken();\n    showLogin();\n    showToast('Session expired — please log in again', true);\n  }\n  return res;\n}\n\n// ---------- Client-side image compression ----------\n// Resizes to maxWidth and re-encodes as JPEG at the given quality so uploads stay small & fast.\nfunction compressImage(file, maxWidth, quality) {\n  return new Promise((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onload = (e) => {\n      const img = new Image();\n      img.onload = () => {\n        const scale = Math.min(1, maxWidth / img.width);\n        const canvas = document.createElement('canvas');\n        canvas.width = img.width * scale;\n        canvas.height = img.height * scale;\n        const ctx = canvas.getContext('2d');\n        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);\n        resolve(canvas.toDataURL('image/jpeg', quality));\n      };\n      img.onerror = reject;\n      img.src = e.target.result;\n    };\n    reader.onerror = reject;\n    reader.readAsDataURL(file);\n  });\n}\n\n// ---------- Backgrounds ----------\ndocument.getElementById('saveBg').addEventListener('click', async () => {\n  const file = document.getElementById('bgFile').files[0];\n  if (!file) return showToast('Choose an image first', true);\n  const dataUrl = await compressImage(file, 1600, 0.72);\n  await saveSetting('background_image', dataUrl);\n});\n\ndocument.getElementById('saveScoreboard').addEventListener('click', async () => {\n  const file = document.getElementById('scoreboardFile').files[0];\n  if (!file) return showToast('Choose an image first', true);\n  const dataUrl = await compressImage(file, 1400, 0.72);\n  await saveSetting('scoreboard_image', dataUrl);\n});\n\nasync function saveSetting(key, value) {\n  try {\n    const res = await authedFetch(`${API}/settings`, {\n      method: 'POST', headers: authHeaders(), body: JSON.stringify({ key, value })\n    });\n    if (!res.ok) throw new Error((await res.json()).error);\n    showToast('Saved — live for everyone now ✅');\n  } catch (e) {\n    showToast(e.message, true);\n  }\n}\n\n// ---------- Players ----------\nasync function loadPlayersAdmin() {\n  const res = await fetch(`${API}/players`);\n  const players = await res.json();\n\n  document.getElementById('playerList').innerHTML = players.map(p => `\n    <div class=\"player-stat-row\" style=\"padding:6px 0; border-top:none;\">\n      ${p.photo ? `<img src=\"${p.photo}\">` : `<div style=\"width:30px;height:30px;border-radius:50%;background:#222;\"></div>`}\n      <div class=\"name\">${p.name}</div>\n    </div>\n  `).join('');\n\n  const select = document.getElementById('playerSelect');\n  select.innerHTML = players.map(p => `<option value=\"${p.id}\">${p.name}</option>`).join('');\n\n  const mPlayer = document.getElementById('mPlayer');\n  mPlayer.innerHTML = players.map(p => `<option value=\"${p.id}\">${p.name}</option>`).join('');\n}\n\ndocument.getElementById('savePlayer').addEventListener('click', async () => {\n  const id = document.getElementById('playerSelect').value;\n  const file = document.getElementById('playerPhoto').files[0];\n  if (!file) return showToast('Choose a photo first', true);\n  const photo = await compressImage(file, 400, 0.75);\n  try {\n    const res = await authedFetch(`${API}/players/${id}`, {\n      method: 'PUT', headers: authHeaders(), body: JSON.stringify({ photo })\n    });\n    if (!res.ok) throw new Error((await res.json()).error);\n    showToast('Player photo updated ✅');\n    loadPlayersAdmin();\n  } catch (e) {\n    showToast(e.message, true);\n  }\n});\n\n// ---------- Tournaments ----------\ndocument.getElementById('createTournament').addEventListener('click', async () => {\n  const type = document.getElementById('tType').value;\n  const name = document.getElementById('tName').value.trim();\n  const yt_link = document.getElementById('tYt').value.trim();\n  if (!name) return showToast('Tournament name required', true);\n  try {\n    const res = await authedFetch(`${API}/tournaments`, {\n      method: 'POST', headers: authHeaders(), body: JSON.stringify({ name, type, yt_link })\n    });\n    if (!res.ok) throw new Error((await res.json()).error);\n    showToast(`New ${type} tournament is now Latest ✅`);\n    document.getElementById('tName').value = '';\n    document.getElementById('tYt').value = '';\n    refreshMatchTournamentLabel();\n  } catch (e) {\n    showToast(e.message, true);\n  }\n});\n\n// ---------- Match results ----------\nlet activeMatchTournament = null;\n\nasync function refreshMatchTournamentLabel() {\n  const type = document.getElementById('mType').value;\n  const res = await fetch(`${API}/tournaments/latest?type=${type}`);\n  const t = await res.json();\n  activeMatchTournament = t;\n  const label = document.getElementById('mTournamentLabel');\n  label.textContent = t\n    ? `Adding to: \"${t.name}\" (${type})`\n    : `No latest ${type} tournament yet — create one above first.`;\n}\ndocument.getElementById('mType').addEventListener('change', refreshMatchTournamentLabel);\n\nfunction updateTotalPreview() {\n  const kills = Number(document.getElementById('mKills').value) || 0;\n  const kpv = Number(document.getElementById('mKillPointValue').value) || 0;\n  const pp = Number(document.getElementById('mPositionPoints').value) || 0;\n  document.getElementById('totalPreview').textContent = pp + kills * kpv;\n}\n['mKills', 'mKillPointValue', 'mPositionPoints'].forEach(id =>\n  document.getElementById(id).addEventListener('input', updateTotalPreview)\n);\n\ndocument.getElementById('saveMatch').addEventListener('click', async () => {\n  if (!activeMatchTournament) return showToast('Create a tournament for this type first', true);\n  const body = {\n    tournament_id: activeMatchTournament.id,\n    player_id: Number(document.getElementById('mPlayer').value),\n    match_number: Number(document.getElementById('mNumber').value),\n    map: document.getElementById('mMap').value,\n    kills: Number(document.getElementById('mKills').value),\n    position: Number(document.getElementById('mPosition').value),\n    position_points: Number(document.getElementById('mPositionPoints').value),\n    kill_point_value: Number(document.getElementById('mKillPointValue').value)\n  };\n  try {\n    const res = await authedFetch(`${API}/matches`, {\n      method: 'POST', headers: authHeaders(), body: JSON.stringify(body)\n    });\n    if (!res.ok) throw new Error((await res.json()).error);\n    showToast('Match result saved — live on homepage ✅');\n  } catch (e) {\n    showToast(e.message, true);\n  }\n});\n\nasync function initAdmin() {\n  await loadPlayersAdmin();\n  await refreshMatchTournamentLabel();\n  updateTotalPreview();\n}\n\n// On page load, if a session token is already stored (tab refresh), try it —\n// a real write endpoint isn't ideal to probe, so we just attempt to load\n// players (public endpoint) and separately trust the token until a write 401s.\n(function checkExistingSession() {\n  if (getToken()) {\n    showAdmin();\n  } else {\n    showLogin();\n  }\n})();\n";
